[Argument]
vsgogojihhks_enable = switch,true,false,tag=中国国际航空-脚本开关

[Script]
response if ${url} ~= /^https:\/\/m\.airchina\.com\.cn\/airchina\/gateway\/v\d(\.\d)*\/api\/services/i then script("https://raw.githubusercontent.com/zirawell/R-Store/main/Res/Scripts/AntiAd/airchina.js") with enable=${vsgogojihhks_enable}, tag="中国国际航空", timeout=60

[MITM]
hostname = m.airchina.com.cn
